#include <cstdio>
#include <cstdlib>

static char *ibuf;
static size_t ipos = 0, ilen = 0;

static inline int gc() { return ipos < ilen ? (unsigned char)ibuf[ipos++] : -1; }

static inline long readNum() {
    int c = gc();
    while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = gc();
    long v = 0;
    while (c >= '0' && c <= '9') { v = v * 10 + (c - '0'); c = gc(); }
    return v;
}

static inline char readLetter() {
    int c = gc();
    while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = gc();
    return (char)c;
}

int main() {
    size_t cap = 1 << 20;
    ibuf = (char*)malloc(cap);
    while (true) {
        if (ilen == cap) { cap <<= 1; ibuf = (char*)realloc(ibuf, cap); }
        size_t r = fread(ibuf + ilen, 1, cap - ilen, stdin);
        if (r == 0) break;
        ilen += r;
    }

    long N = readNum();
    long M = readNum();
    long P = readNum();

    int *Qr = (int*)malloc(sizeof(int) * (N + 1));
    int *Qc = (int*)malloc(sizeof(int) * (M + 1));
    for (long i = 1; i <= N; i++) Qr[i] = (int)i;
    for (long j = 1; j <= M; j++) Qc[j] = (int)j;

    for (long p = 0; p < P; p++) {
        char letter = readLetter();
        long a = readNum();
        long b = readNum();
        if (letter == 'L') {
            int t = Qr[a]; Qr[a] = Qr[b]; Qr[b] = t;
        } else {
            int t = Qc[a]; Qc[a] = Qc[b]; Qc[b] = t;
        }
    }

    size_t omax = (size_t)N * (size_t)M * 8 + 16;
    char *obuf = (char*)malloc(omax);
    size_t opos = 0;

    for (long i = 1; i <= N; i++) {
        long rb = (long)(Qr[i] - 1) * M;
        for (long j = 1; j <= M; j++) {
            long v = rb + Qc[j];
            char tmp[12];
            int len = 0;
            if (v == 0) tmp[len++] = '0';
            while (v > 0) { tmp[len++] = (char)('0' + v % 10); v /= 10; }
            if (j > 1) obuf[opos++] = ' ';
            while (len > 0) obuf[opos++] = tmp[--len];
        }
        obuf[opos++] = '\n';
    }

    fwrite(obuf, 1, opos, stdout);
    return 0;
}
